def guide_doc():
 w=Writer();w.flow=True
 w.doc.styles['Normal'].font.size=Pt(12);w.doc.styles['Normal'].paragraph_format.line_spacing=1.15
 for name in ['Heading 1','Heading 2']:
  st=w.doc.styles[name];st.font.size=Pt(13);st.paragraph_format.line_spacing=1.15;st.paragraph_format.first_line_indent=Mm(0)
 w.p('Защита банковской системы за три минуты','Title')
 w.p(f'{AUTHOR} · {GROUP}',align=C,indent=0,after=12)
 sub(w,'Что изменено и где открывать',
 'Тема теперь точно соответствует варианту 5: банковская система, включая карты и кредиты. В записке сохранены все шесть исходных сущностей, добавлены сотрудники и плановые платежи. На титуле стоят твои данные. Все шесть приложений А–Е следуют новому образцу, а 30 диаграмм построены кодом.',
 'Для показа держи четыре опоры: Г.3 — проблема, гипотеза, решение и проверка; Г.1 — содержательные компоненты облика; Д.2 — какие модули реализуют каждый компонент; Е.1 — как измеряется качество. Рисунки А.1/А.2 показывают вариант целиком, В.4/В.5 — важные процессы.',
 'Главная мысль преподавателя: из того, что использован backend, frontend или PostgreSQL, ещё не следует польза. Нужно показать потребность, измеримую норму результата и механизм, которым состав системы её обеспечивает. В записке это цепочка из четырёх гипотез и критериев КР1–КР6.')
 w.page('Текст выступления на три минуты',1)
 speech=[
 ('0:00–0:30','Я разработал проект по варианту пять «Банковская система». Он охватывает клиентов, отделения, счета, карты, переводы и кредитные договоры. Проблема связана не с отсутствием базы данных, а с тем, что сотруднику нужен согласованный результат сразу в нескольких реестрах, тогда как раздельный учёт допускает ошибки и требует повторного переноса сведений.'),
 ('0:30–1:00','Я сформулировал четыре проверяемые гипотезы: единый клиентский контекст исключает противоречивые реквизиты; атомарное проведение защищает перевод; единый расчёт согласует кредитный план; общая модель даёт проверяемые отчёты. Качество оценивается по результативности, оперативности и затратности действий пользователя. Решающий показатель — три из трёх законченных задач с правильным результатом.'),
 ('1:00–1:35','Из документов получены сущности и связи. Из назначения выведены пять функций, а из процессных развилок — требования к атомарности, повтору, сроку карты, графику и времени ответа. Обобщение этих действий дало шесть содержательных компонентов: клиентский контекст, карты, переводы, кредитный учёт, контроль результатов и доверие к действиям. Каждый компонент нужен конкретной функции.'),
 ('1:35–2:05','Технический проект раскрывает эти компоненты в одиннадцать модулей. Например, компонент переводов реализуют подготовка команды и транзакционное проведение; кредитный компонент — договоры и расчёт графика. У каждого модуля указаны вход, выход, правила и проверка. Интерфейсы облика сохраняются. Принципы функционирования — проверка до записи, единый исход и проверяемая история; развитие идёт через версии интерфейсов и миграции.'),
 ('2:05–2:40','ПМИ проверяет всю цепочку обратно, от модулей к назначению. У тридцати трёх требований есть двадцать три сценария с эталонами. При двух списаниях по семь тысяч из десяти тысяч должен пройти один перевод. При ошибке после списания всё откатывается. В кредитном графике доли до копейки дают основную сумму. Наблюдение фиксируется вместе со сборкой, данными и свидетельствами.'),
 ('2:40–3:00','Завершает проверку представитель банка: клиент–счёт–карта, перевод–выписка, договор–график–сводка. Каждая задача должна дать верный ответ не более чем за две минуты, без SQL и повторного переноса реквизитов. Так проверяется качество применения. Сейчас подготовлен технический проект и методика; фактическая приёмка выполняется после реализации.')]
 for timing,t in speech:
  w.p(timing,size=12,indent=0,before=7,keep=True);w.p(t,size=12,indent=0,after=3)
 w.page('Как отвечать по цепочке преподавателя',1)
 qa=[
 ('Какая потребность и в чём противоречие','Сотрудник хочет закончить обращение с согласованным результатом. Раздельные реестры позволяют проверить его лишь последующей сверкой. Поэтому нормы качества заданы до технологий.'),
 ('Как измерить удовлетворённость','Через способность представителя банка завершить три заданные задачи правильно, за установленное время и без лишнего переноса данных. Это операциональная мера, а не выдуманный опрос с оценкой пять.'),
 ('Почему такие компоненты','Каждый обобщает повторяющуюся содержательную работу процессов. Кредитный план нужен F4, проведение — F3, клиентский контекст — всем маршрутам. Матрица в Г показывает отсутствие ненужных компонентов и необеспеченных функций.'),
 ('Чем архитектура отличается от технического проекта','Архитектура задаёт облик, ответственность и принципы без зависимости от конкретного продукта. Технический проект показывает, какие модули, данные, алгоритмы и средства реализуют этот облик.'),
 ('Что конкретно писать','На Д.2 показаны М01–М11. В приложении Д у каждого есть вход, выход, правило и тест. Например, М07 возвращает полный график, М05 — однозначный денежный исход.'),
 ('Как обеспечивается развитие','Новая формула меняет М07 за контрактом плана; новый отчёт — М08/М09; данные развиваются миграциями. Связанные эталоны и сквозные маршруты проверяются снова.'),
 ('Почему внутренние тесты не равны качеству','Они подтверждают отдельные правила. Назначение проверяется полной пользовательской задачей и сравнением её результата, времени и усилий с нормой.'),
 ('Кредитный график — это деньги','Это план по утверждённым условиям. Выдачу и оплату подтверждает кредитная служба. По одному графику нельзя объявить фактическую просрочку. Такой границы нужно придерживаться на защите.'),
 ('Надо ли уже иметь весь код курсовой','По сообщениям сейчас защищаются проектирование и ПМИ. ГОСТ 19.101–2024 различает записку технического проекта и текст программы рабочего проекта. Не заявляй готовность программы или запуск её испытаний без фактов.'),
 ]
 for title,t in qa:sub(w,title,t)
 w.page('Карта схем и точные примеры',1)
 for title,t in [
 ('А — документы и данные','А.1: клиент, отделение, счёт и сотрудник. А.2: карты, перевод, кредит и график. А.3: потребитель, требование, критерий, проверка, наблюдение и свидетельство. А.4/А.5: все поля и 12 FK.'),
 ('Б — функции','Контекст, уровень 1, дерево и пять детальных DFD. Стрелка означает данные. Повтор D — один ресурс. Не рассказывай по DFD временную последовательность.'),
 ('В — процессы','BPMN показывает кто, что дальше и при каком условии. Ромб выбирает ветвь, плюс раскрывает подпроцесс. Простые листья описаны спецификацией; все 15 листьев учтены.'),
 ('Г — облик и обоснование','Сначала покажи Г.2 — обобщённую работу, затем Г.1 — нужные компоненты и интерфейсы, затем Г.3 — связь с гипотезами и измерением.'),
 ('Д — техника','Д.1: где размещено. Д.2: К → М → средства. Д.3: проведение. Д.4: график. Д.5: конкуренция. Д.6: взаимодействие интерфейса, сервиса и БД.'),
 ('Е — измерение','Е.1 показывает получение факта и свидетельства. В таблицах — связи требований, сценарии, эталон данных и форма будущего протокола.'),
 ('Перевод','A=10 000, B=1000; 2500 → A=7500, B=3500. При сбое после списания — исходные остатки. Повтор — тот же ID без второго списания.'),
 ('Кредит','120 000 под 12 % с 01.01.2026; даты 01.02, 01.03, 01.04. Основные части — по 40 000; проценты — 1223,01; 736,44; 407,67. Для 100,01 под 0 % три части — 33,33; 33,33; 33,35.'),
 ('Что готово','Проверены документы, схемы и арифметические эталоны. ПМИ банковского ПО пока задаёт будущие испытания. В PDF все шрифты должны быть встроены, чтобы читать с Mac.')]:sub(w,title,t)
 w.save(GUIDE)
 return {'guide':str(GUIDE),'speech_words':sum(len(t.split()) for _,t in speech)}

